module phone_network(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] valid_detectors,\n    input wire [7:0] pos_0,\n    input wire [7:0] pos_1,\n    input wire [7:0] pos_2,\n    input wire [7:0] pos_3,\n    input wire [7:0] pos_4,\n    input wire [7:0] pos_5,\n    input wire [7:0] pos_6,\n    input wire [7:0] pos_7,\n    input wire [31:0] count_0,\n    input wire [31:0] count_1,\n    input wire [31:0] count_2,\n    input wire [31:0] count_3,\n    input wire [31:0] count_4,\n    input wire [31:0] count_5,\n    input wire [31:0] count_6,\n    input wire [31:0] count_7,\n    output reg [31:0] result,\n    output reg done\n);\n    \n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] SORT = 2'd1;\n    localparam [1:0] CALC = 2'd2;\n    localparam [1:0] DONE_STATE = 2'd3;\n    \n    reg [1:0] state;\n    reg [7:0] sorted_pos [0:7];\n    reg [31:0] sorted_count [0:7];\n    reg [2:0] n_valid;\n    reg [2:0] outer_idx;\n    reg [2:0] inner_idx;\n    reg [2:0] calc_idx;\n    reg [31:0] temp_result;\n    reg swap_flag;\n    integer i;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            n_valid <= 3'd0;\n            outer_idx <= 3'd0;\n            inner_idx <= 3'd0;\n            calc_idx <= 3'd0;\n            temp_result <= 32'd0;\n            swap_flag <= 1'b0;\n            for (i = 0; i < 8; i = i + 1) begin\n                sorted_pos[i] <= 8'd0;\n                sorted_count[i] <= 32'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        sorted_pos[0] <= pos_0;\n                        sorted_pos[1] <= pos_1;\n                        sorted_pos[2] <= pos_2;\n                        sorted_pos[3] <= pos_3;\n                        sorted_pos[4] <= pos_4;\n                        sorted_pos[5] <= pos_5;\n                        sorted_pos[6] <= pos_6;\n                        sorted_pos[7] <= pos_7;\n                        \n                        sorted_count[0] <= count_0;\n                        sorted_count[1] <= count_1;\n                        sorted_count[2] <= count_2;\n                        sorted_count[3] <= count_3;\n                        sorted_count[4] <= count_4;\n                        sorted_count[5] <= count_5;\n                        sorted_count[6] <= count_6;\n                        sorted_count[7] <= count_7;\n                        \n                        n_valid <= valid_detectors;\n                        outer_idx <= 3'd0;\n                        inner_idx <= 3'd0;\n                        state <= SORT;\n                    end\n                end\n                \n                SORT: begin\n                    if (outer_idx < n_valid - 3'd1) begin\n                        if (inner_idx < n_valid - 3'd1 - outer_idx) begin\n                            if (sorted_pos[inner_idx] > sorted_pos[inner_idx + 3'd1]) begin\n                                sorted_pos[inner_idx] <= sorted_pos[inner_idx + 3'd1];\n                                sorted_pos[inner_idx + 3'd1] <= sorted_pos[inner_idx];\n                                \n                                sorted_count[inner_idx] <= sorted_count[inner_idx + 3'd1];\n                                sorted_count[inner_idx + 3'd1] <= sorted_count[inner_idx];\n                                \n                                swap_flag <= 1'b1;\n                            end\n                            inner_idx <= inner_idx + 3'd1;\n                        end else begin\n                            outer_idx <= outer_idx + 3'd1;\n                            inner_idx <= 3'd0;\n                        end\n                    end else begin\n                        calc_idx <= 3'd1;\n                        temp_result <= sorted_count[3'd0];\n                        state <= CALC;\n                    end\n                end\n                \n                CALC: begin\n                    if (calc_idx < n_valid) begin\n                        if (sorted_count[calc_idx] > sorted_count[calc_idx - 3'd1]) begin\n                            temp_result <= temp_result + (sorted_count[calc_idx] - sorted_count[calc_idx - 3'd1]);\n                        end\n                        calc_idx <= calc_idx + 3'd1;\n                    end else begin\n                        result <= temp_result;\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule